internal static class MetricsGlossary
{
    private const string Content = """
        # Metrics Glossary

        ## NLP (Tier 1 — deterministic, no LLM)

        | Metric | Description |
        |--------|-------------|
        | Words  | Word count of the response. Sanity check for non-empty, reasonable-length output. |
        | BLEU   | N-gram overlap with reference response(s). Higher = closer to reference. |
        | GLEU   | Sentence-level BLEU variant. |
        | F1     | Unigram-level F1 between response and ground truth. |

        ## Quality (Tier 2 — LLM-as-judge, requires EVAL_USE_REAL_JUDGE=1)

        | Metric        | Description |
        |---------------|-------------|
        | Relevance     | How relevant is the response to the query. |
        | Coherence     | Logical, orderly presentation. |
        | Fluency       | Grammar and readability. |
        | Completeness  | Comprehensive and accurate vs ground truth. |
        | Equivalence   | Similarity vs ground truth with respect to the query. |
        | Groundedness  | Alignment with given context. |
        """;

    public static void WriteTo(string directory)
    {
        Directory.CreateDirectory(directory);
