internal static class Thresholds
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    private static ThresholdsDocument? s_doc;

    private static ThresholdsDocument Doc => s_doc ??= Load();

    private static ThresholdsDocument Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return new();
        return JsonSerializer.Deserialize<ThresholdsDocument>(File.ReadAllText(path), s_options) ?? new();
    }

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        if (!Doc.HardFail) return;

        foreach (var metric in result.Metrics)
        {
            if (Doc.Thresholds.TryGetValue(metric.Key, out var threshold))
            {
                if (metric.Value is NumericMetric numeric && threshold.MinValue.HasValue)
                {
                    if (numeric.Value < threshold.MinValue)
                        Assert.Fail($"[{scenarioId}] {metric.Key} = {numeric.Value} < threshold {threshold.MinValue}");
                }
            }
        }
    }
}

