namespace MyApp.Evals.Tests;

internal record TelemetryRecord(
    string AgentName,
    string Model,
    int InputTokens,
    int OutputTokens,
    long LatencyMs);

internal static class TelemetryStore
{
    private static readonly List<TelemetryRecord> s_records = new();
    private static readonly object s_lock = new();

    public static void Record(TelemetryRecord r)
    {
        lock (s_lock) { s_records.Add(r); }
    }

    public static void FlushTo(string outputDir)
    {
        Directory.CreateDirectory(outputDir);
        List<TelemetryRecord> snapshot;
        lock (s_lock) { snapshot = s_records.ToList(); }

        // JSON
        var json = JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(Path.Combine(outputDir, "telemetry.json"), json);

        // Markdown table
        var md = new System.Text.StringBuilder();
        md.AppendLine("| Agent | Model | Input Tokens | Output Tokens | Latency (ms) |");
        md.AppendLine("|-------|-------|-------------|--------------|-------------|");
        foreach (var r in snapshot)
            md.AppendLine($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} |");
        File.WriteAllText(Path.Combine(outputDir, "telemetry.md"), md.ToString());
    }
}

