namespace MyApp.Evals.Tests;

/// <summary>
/// Writes a metrics-glossary.md alongside report.html so reviewers can
/// look up what each column means without leaving the report folder.
/// </summary>
internal static class MetricsGlossary
{
    private const string Content = """
        # Metrics Glossary

        ## NLP (Tier 1 — deterministic, no LLM)

        | Metric | Description |
        |--------|-------------|
        | Words  | Word count of the response. Sanity check for non-empty, reasonable-length output. |
        | BLEU   | N-gram overlap with reference response(s). Higher = closer to reference. |
        | GLEU   | Sentence-level BLEU variant. |
        | F1     | Unigram-level F1 between response and ground truth. |

        ## Quality (Tier 2 — LLM-as-judge, requires EVAL_USE_REAL_JUDGE=1)

        | Metric        | Description |
        |---------------|-------------|
        | Relevance     | How relevant is the response to the query. |
        | Coherence     | Logical, orderly presentation. |
        | Fluency       | Grammar and readability. |
        | Completeness  | Comprehensive and accurate vs ground truth. |
        | Equivalence   | Similarity vs ground truth with respect to the query. |
        | Groundedness  | Alignment with given context. |
        """;

    public static void WriteTo(string directory)
    {
        Directory.CreateDirectory(directory);
        File.WriteAllText(Path.Combine(directory, "metrics-glossary.md"), Content);
    }
}

namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:1
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts, the entry assembly is testhost.exe so user-secrets
        // are NOT auto-loaded. Add them explicitly.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        builder.AddAzureOpenAIChatClient("chat");
        var host = builder.Build();
        try
        {
            return host.Services.GetRequiredService<IChatClient>();
        }
        catch (InvalidOperationException ex)
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost populates this at " +
                "runtime, but `dotnet test` runs standalone. Wire one of:\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" " +
                "--project MyApp.Evals.Tests\n",
                ex);
        }
    }
}

