/// <summary>
/// A deterministic stub that returns canned responses when no real agent is wired.
/// Enables Tier 1 (NLP) evals to run without any credentials.
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMessage = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var response = GenerateResponse(userMessage);
        return Task.FromResult(new ChatResponse(new ChatMessage(ChatRole.Assistant, response))
        {
            ModelId = "stub"
        });
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Stub does not support streaming.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }

    private static string GenerateResponse(string input)
    {
        return $"This is a stub response for evaluation purposes. " +
               $"The user asked about: {input}. " +
               "I would normally provide a helpful and detailed answer to this question, " +
               "covering the key aspects of the topic with relevant information and examples.";
    }
}

